function extended_gcd(a: int, b: int) returns (gcd: int, x: int, y: int)
  requires a >= 0 && b >= 0
{
  if b == 0 then
    (a, 1, 0)
  else
    // Iterative implementation
    var (old_r, r) := (a, b);
    var (old_s, s) := (1, 0);
    var (old_t, t) := (0, 1);

    while r != 0
      invariant old_r == a * old_s + b * old_t
      invariant r == a * s + b * t
      invariant gcd(a, b) == gcd(old_r, r)
    {
      var quotient := old_r / r;
      var (new_r, new_s, new_t) := (old_r - quotient * r, old_s - quotient * s, old_t - quotient * t);
      old_r, old_s, old_t := r, s, t;
      r, s, t := new_r, new_s, new_t;
    }

    (old_r, old_s, old_t)
}

// Helper lemma to prove properties of extended GCD
lemma extended_gcd_properties(a: int, b: int)
  requires a >= 0 && b >= 0
  ensures exists gcd: int, x: int, y: int :: 
    gcd == extended_gcd(a, b).0 &&
    x == extended_gcd(a, b).1 &&
    y == extended_gcd(a, b).2 &&
    gcd == a * x + b * y &&
    (forall d: int :: d | a && d | b ==> d | gcd)
{
  // The properties are inherent in the extended_gcd function implementation
}

// Method to compute modular inverse
method compute_inverse(a: int, m: int) returns (inv: int, exists: bool)
  requires m > 0
  requires 0 <= a < m
{
  var (gcd, x, y) := extended_gcd(a, m);

  if gcd == 1 then {
    // Modular inverse exists
    exists := true;
    // Ensure inv is in range [0, m-1]
    inv := (x % m + m) % m;
  } else {
    // Modular inverse doesn't exist
    exists := false;
    inv := 0;
  }
}

// Test method
method test_compute_inverse() {
  var inv: int;
  var exists: bool;

  // Test case 1: 3 and 11 are coprime
  inv, exists := compute_inverse(3, 11);
  assert exists;
  assert (3 * inv) % 11 == 1;

  // Test case 2: 2 and 4 are not coprime
  inv, exists := compute_inverse(2, 4);
  assert !exists;

  // Test case 3: 7 and 13 are coprime
  inv, exists := compute_inverse(7, 13);
  assert exists;
  assert (7 * inv) % 13 == 1;
}

